    for k, v in (('alpha', '100'), ('beta', '200'), ('gamma', '300')):
        m, body = attempt('PUT', f"{ep}/{k}", {'value': v})
        print(f"PUT {ep}/{k} = {v}  ->  {m}: {body[:120]}")
    print()
